// PoolStats contains statistics for a connection pool at a specific address.
type PoolStats struct {
	Address      string // Remote address
	PoolSize     uint32 // Maximum pool size
	ActiveCount  int    // Number of active connections
	TotalSlots   int    // Total connection slots
	ShortConnMod bool   // Whether using short connection mode
}

// Dump returns diagnostic information about all connection pools.
// Returns a map of address to PoolStats for inspection and debugging.
func (p *connPool) Dump() map[string]PoolStats {
	result := make(map[string]PoolStats)

	p.conns.Range(func(key, value interface{}) bool {
		address := key.(string)
		trans := value.(*transports)

		activeCount := 0
		totalSlots := int(trans.size)

		for i := 0; i < totalSlots; i++ {
			if cliTransport := trans.cliTransports[i]; cliTransport != nil {
				if cliTransport.(grpc.IsActive).IsActive() {
					activeCount++
				}
			}
		}

		result[address] = PoolStats{
			Address:      address,
			PoolSize:     p.size,
			ActiveCount:  activeCount,
			TotalSlots:   totalSlots,
			ShortConnMod: p.connOpts.ShortConn,
		}
		return true
	})

	return result
}

