// FallbackStrategyError wraps errors from the codec fallback chain.
// The fallback strategy attempts: FastCodec → Frugal → Apache Thrift.
// This function aggregates all attempted strategies and their errors for diagnostics.
func FallbackStrategyError(err error, strategy string, errors []string) error {
	var errMsgs []string
	if err != nil {
		errMsgs = append(errMsgs, fmt.Sprintf("error: %v", err))
	}
	for _, errStr := range errors {
		errMsgs = append(errMsgs, fmt.Sprintf("fallback attempted: %s", errStr))
	}
	return fmt.Errorf("thrift codec fallback chain failed after trying [%s]; accumulated errors: %s", 
		strategy, strings.Join(errMsgs, "; "))
}

